 vals=set();v=0;prev=0;basis=list(Q.values())
 for i in range(1<<len(basis)):
  gray=i^(i>>1)
  if i:v^=basis[(gray^prev).bit_length()-1]
  prev=gray;vals.add(v.bit_count())
 return sorted(vals)

